// Advanced content: the advanced strikes tier (unlocks after phase 3), feints, setups and
// traps, signature moves of great fighters, and self-defence scenarios.
// Each item is a learnable skill like the combinations in combos.js, with its own motion:
// real captures cut and chained (see mocap.js). A piece with opts.alt falls back to that
// piece if its capture is not in assets/fighter.glb.
import { WIN } from './combos.js';

export const ADV_DISCIPLINES = {
  advanced: { en: 'Advanced strikes', ka: 'მოწინავე დარტყმები' },
  setups: { en: 'Feints, setups & traps', ka: 'ფინტები, მომზადება და ხაფანგები' },
  signature: { en: 'Signature moves', ka: 'ცნობილი მებრძოლების ილეთები' },
  selfdef: { en: 'Self-defence', ka: 'თავდაცვა' },
};

// Captions shown under the animation (Georgian in ADV_KA_UI below).
const P = (clip, from, to, lab, o = {}) => [clip, from, to, { lab, ...o }];
const w = (clip, i) => WIN[clip][i];
// A clip cut to its active part: first starts from guard, last returns to guard.
const cut = (clip, lab, first, last, o) => P(clip, first ? 0 : w(clip, 0), last ? 1 : w(clip, 1), lab, o);
const hold = (clip, at, secs, lab) => P(clip, at, at, lab, { hold: secs });

// Body-shot layer for the lead hook when the body-hook capture is missing: dip and lean to the lead side.
